m as (
  select distinct on (q.qr_id) q.qr_id, c.id app_court,
    6371000 * 2 * asin(sqrt(power(sin(radians(c.latitude::float - q.lat)/2),2) + cos(radians(q.lat))*cos(radians(c.latitude::float))*power(sin(radians(c.longitude::float - q.lon)/2),2))) dist
  from qr q join court c on c.latitude is not null
    and abs(c.latitude::float - q.lat) < 0.01 and abs(c.longitude::float - q.lon) < 0.012
  order by q.qr_id, dist
),
mm as (select * from m where dist <= 400),
firsts as (select "userId", min(check_in_time) t from user_check_in group by 1),
ci as (
  select mm.qr_id, to_char(date_trunc('month', k.check_in_time),'YYYY-MM') mo, count(*) n
  from mm join user_check_in k on k."courtId" = mm.app_court and k.check_in_time >= '2026-01-01'
  group by 1,2),
fc as (
  select mm.qr_id, to_char(date_trunc('month', f.t),'YYYY-MM') mo, count(*) n
  from firsts f join user_check_in k on k."userId" = f."userId" and k.check_in_time = f.t
  join mm on mm.app_court = k."courtId" where f.t >= '2026-01-01' group by 1,2)
select json_build_object(
  'matched', (select count(*) from mm),
  'map', (select json_agg(json_build_array(qr_id, app_court, round(dist::numeric))) from mm),
  'checkins', (select json_agg(json_build_array(qr_id, mo, n)) from ci),
  'firsts', (select json_agg(json_build_array(qr_id, mo, n)) from fc),
  'national', (select json_agg(json_build_array(mo, users, checkins)) from (
      select to_char(d,'YYYY-MM') mo,
        (select count(*) from "user" u where date_trunc('month', u.created_at) = d) users,
        (select count(*) from user_check_in k where date_trunc('month', k.check_in_time) = d) checkins
      from generate_series('2026-01-01'::timestamp, date_trunc('month', now()), '1 month') d) x)
)::text as payload;
